package com.hssa.common.util; import org.springframework.data.domain.PageRequest; import org.springframework.data.domain.Pageable; import org.springframework.data.domain.Sort; public final class PaginationUtils { private PaginationUtils() {} public static Pageable createPageable(int page, int size, String sortBy, String direction) { Sort sort = Sort.unsorted(); if (sortBy != null && !sortBy.trim().isEmpty()) { sort = Sort.by(Sort.Direction.fromString(direction), sortBy); } return PageRequest.of(page, size, sort); } }
